// Items. Ids below ITEM_BASE are block items (same number as the block's canonical
// state); ids from ITEM_BASE up are pure items. All tables are generated by
// tools/gen_content.py from the full Minecraft item list.
#ifndef ITEM_H
#define ITEM_H
#include "../core/common.h"
#include "../gen/content.h"

typedef enum { ARMOR_NONE = -1, ARMOR_HEAD = 0, ARMOR_CHEST, ARMOR_LEGS, ARMOR_FEET } ArmorSlot;

typedef struct {
    const char *name, *key;
    u8 category, tab, max_stack;
    s16 icon;              // index in items.png; -1 = isometric block, -2 = flat block tile
    u16 block;             // block state placed when used (0 = none)
    u8 tool, tier;         // ToolType; harvest tier 1 wood/gold, 2 stone/copper, 3 iron, 4 diamond/netherite
    f32 dig_speed;         // multiplier when the tool matches
    u16 durability;        // 0 = unbreakable
    f32 attack_damage;     // damage dealt in melee
    f32 attack_speed;      // full-strength attacks per second
    u8 food, saturation10; // hunger restored, saturation*10
    s8 armor_slot;
    u8 armor_points, toughness10, kb_res10;
    u16 fuel_ticks;        // burn time in a furnace (Minecraft 20 tick/s scale)
    u8 use;                // ItemUse behaviour
    u16 use_arg;           // mob / projectile / disc index
    u16 remainder;         // item left in the grid / hand after use (bucket, bowl, bottle)
    u8 fx_n;
    u16 fx[4][4];          // food side effects: effect, amplifier, seconds, chance%
    u8 variants;           // >0: ItemStack.damage selects a variant (potion type)
    bool obtainable;       // survival obtainable
} ItemDef;

typedef struct { const char *name, *key; u8 effect, amplifier; u16 seconds; u32 color; } PotionDef;
extern ItemDef ITEMS[ITEM_MAX];
extern const PotionDef POTIONS[POTION_COUNT];
extern const char *EFFECT_NAMES[EFFECT_COUNT];
extern const char *DISC_NAMES[DISC_COUNT];
void items_init(void);
static inline bool item_valid(int id) { return id > 0 && id < ITEM_MAX && ITEMS[id].name != NULL; }
const char *item_name(int id);
const char *stack_name(u16 id, u16 damage);   // includes potion type
int item_by_key(const char *key);             // 0 if unknown (accepts "minecraft:" prefix)
static inline bool item_is_block(int id) { return id > 0 && id < ITEM_BASE; }

#define MAX_ENCH 5
// damage = durability used, or variant (potion type). ench = (enchantment id, level) pairs (banners: (pattern, colour)
// layers). rcost = anvil prior-work count. data = map id. name = custom name (index into the world's name table).
typedef struct { u16 id; u8 count; u8 rcost; u16 damage; u16 data; u16 name; u8 ench[MAX_ENCH][2]; } ItemStack;
static inline bool stack_empty(ItemStack s) { return s.id == 0 || s.count == 0; }
static inline ItemStack stack_of(int id, int n) { ItemStack s; memset(&s, 0, sizeof s); s.id = (u16)id; s.count = (u8)n; return s; }
static inline int stack_max(ItemStack s) { return item_valid(s.id) ? ITEMS[s.id].max_stack : 64; }
static inline bool stack_same_kind(ItemStack a, ItemStack b) {
    return a.id == b.id && a.damage == b.damage && a.data == b.data && a.name == b.name && a.rcost == b.rcost && !memcmp(a.ench, b.ench, sizeof a.ench);
}
static inline bool stack_can_merge(ItemStack a, ItemStack b) { return stack_same_kind(a, b) && ITEMS[a.id].max_stack > 1; }

// ---------------------------------------------------------------- enchantments (enchant.c)
enum {
    ENCH_NONE, ENCH_PROTECTION, ENCH_FIRE_PROTECTION, ENCH_FEATHER_FALLING, ENCH_BLAST_PROTECTION, ENCH_PROJECTILE_PROTECTION,
    ENCH_RESPIRATION, ENCH_AQUA_AFFINITY, ENCH_THORNS, ENCH_DEPTH_STRIDER, ENCH_FROST_WALKER, ENCH_BINDING_CURSE, ENCH_SOUL_SPEED,
    ENCH_SWIFT_SNEAK, ENCH_SHARPNESS, ENCH_SMITE, ENCH_BANE_OF_ARTHROPODS, ENCH_KNOCKBACK, ENCH_FIRE_ASPECT, ENCH_LOOTING,
    ENCH_SWEEPING_EDGE, ENCH_EFFICIENCY, ENCH_SILK_TOUCH, ENCH_UNBREAKING, ENCH_FORTUNE, ENCH_POWER, ENCH_PUNCH, ENCH_FLAME,
    ENCH_INFINITY, ENCH_LUCK_OF_THE_SEA, ENCH_LURE, ENCH_LOYALTY, ENCH_IMPALING, ENCH_RIPTIDE, ENCH_CHANNELING, ENCH_MULTISHOT,
    ENCH_QUICK_CHARGE, ENCH_PIERCING, ENCH_MENDING, ENCH_VANISHING_CURSE, ENCH_DENSITY, ENCH_BREACH, ENCH_WIND_BURST, ENCH_COUNT
};
typedef struct {
    const char *key, *name;
    u8 max_level, weight;      // weight: rarity for the enchanting table (10 common .. 1 very rare)
    u16 targets;               // ET_* bits
    u8 group;                  // mutually exclusive group (0 = none)
    u8 min_base, min_step, span;   // enchanting power range: min = base + (lvl-1)*step, max = min + span
    bool treasure, curse;
} EnchantDef;
enum { ET_HEAD = 1, ET_CHEST = 2, ET_LEGS = 4, ET_FEET = 8, ET_SWORD = 16, ET_AXE = 32, ET_DIGGER = 64, ET_BOW = 128, ET_CROSSBOW = 256,
       ET_TRIDENT = 512, ET_ROD = 1024, ET_MACE = 2048, ET_DURABLE = 4096, ET_ANY = 8192 };
#define ET_ARMOR (ET_HEAD | ET_CHEST | ET_LEGS | ET_FEET)
extern const EnchantDef ENCHANTS[ENCH_COUNT];
int ench_level(ItemStack s, int ench);                // 0 if absent
bool ench_add(ItemStack *s, int ench, int level);     // false if no free slot
void ench_remove(ItemStack *s, int ench);
int ench_count(ItemStack s);
u16 item_ench_targets(int id);                        // ET_* bits the item counts as
bool ench_applicable(int ench, int item);             // could appear on this item (books accept everything)
bool ench_compatible(ItemStack s, int ench);          // no conflict with what is already on s
int item_enchantability(int id);                      // 0 = cannot be enchanted at a table
const char *ench_roman(int level);
// enchanting table: picks up to 3 enchantments for an item at a given level cost
int ench_select(int item, int level, u32 seed, u8 out[][2], int max);
int stack_tooltip_lines(ItemStack s, char lines[][64], int max);   // enchantments, patterns, map info
// custom item names (anvil); table saved with the world
u16 item_name_intern(const char *name);
const char *item_name_get(u16 idx);
void item_names_reset(void);
void item_names_save(const char *path);
void item_names_load(const char *path);
const char *stack_display_name(ItemStack s);
const char *banner_pattern_name(int p);
// anvil: combine left + right (repair / merge enchantments / rename); cost in levels, how many of right are used
ItemStack anvil_combine(ItemStack left, ItemStack right, const char *rename, int *cost, int *right_used);
// grindstone: strip non-curse enchantments (optionally merging two damaged items); xp returned
ItemStack grindstone_result(ItemStack a, ItemStack b, int *xp);

// ---------------------------------------------------------------- inventory
#define INV_HOTBAR 9
#define INV_MAIN 36            // slots 0..8 = hotbar, 9..35 = backpack
typedef struct {
    ItemStack slots[INV_MAIN];
    ItemStack armor[4];
    ItemStack offhand;
    int selected;
} Inventory;
int inventory_add(Inventory *inv, ItemStack s);          // returns how many could NOT be added
int inventory_count(const Inventory *inv, int id);
bool inventory_remove(Inventory *inv, int id, int n);
static inline ItemStack *inventory_held(Inventory *inv) { return &inv->slots[inv->selected]; }
int inventory_armor_points(const Inventory *inv);
f32 inventory_armor_toughness(const Inventory *inv);

// ---------------------------------------------------------------- recipes
typedef struct { u16 off, n; } IngredientDef;            // alternatives in ING_ITEMS
typedef struct { u16 result; u8 count, w, h; bool shapeless; u16 ing[9]; } RecipeDef;   // ing: INGREDIENTS index, 0 = empty
typedef struct { u16 ing; u16 result; u8 kinds; u8 xp100; } SmeltDef;                   // kinds: 1 furnace 2 blast 4 smoker 8 campfire
typedef struct { u16 input, result; u8 count; } CutDef;
typedef struct { u16 tmpl, base, addition, result; } SmithDef;
extern const u16 ING_ITEMS[];
extern const IngredientDef INGREDIENTS[ING_COUNT + 1];
extern const RecipeDef RECIPES[RECIPE_COUNT];
extern const SmeltDef SMELTS[SMELT_COUNT];
extern const CutDef CUTS[CUT_COUNT];
extern const SmithDef SMITHS[SMITH_COUNT];
enum { SMELT_FURNACE = 1, SMELT_BLAST = 2, SMELT_SMOKER = 4, SMELT_CAMPFIRE = 8 };

bool ingredient_matches(int ing, int item);
// grid is w*h (2x2 or 3x3); returns the result (empty if nothing matches); *recipe gets the index
ItemStack crafting_match(const ItemStack *grid, int w, int h);
int crafting_match_index(const ItemStack *grid, int w, int h);
int crafting_remainder(int item);            // item left in the grid after crafting (bucket ...)
int smelting_result(int id, int kind_mask);  // 0 = none
f32 smelting_xp(int id);
int fuel_value(int id);
int recipe_count(void);
int stonecutter_options(int input, ItemStack *out, int max);
ItemStack smithing_result(ItemStack tmpl, ItemStack base, ItemStack add);
#endif
